#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        // [C B A] from [A B C]
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };

    for(int placed=0; placed<n-1; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        int rem = n - placed; // remaining elements count

        // We want to move element from pos to placed.
        // Work in the full array. 

        if(rem == 2){
            // Only two left, just need a swap. But x+y < n means x+y <= n-1.
            // op(placed+1, 1): x=placed+1, y=1, x+y=placed+2. Need placed+2<=n-1 => placed<=n-3.
            // rem==2 means placed==n-2, so placed+2=n, which is > n-1. Can't do directly.
            // But if rem==2 and one is wrong, both must be swapped. Let's try op(1, 1) if n>2.
            if(n>2) doOp(1,1);
            // recheck
            continue;
        }

        // Step 1: bring element to position n-1
        if(pos < n-1){
            // x = pos+1, y = 1. Element in A (index pos = x-1), goes to n-x+pos = n-1. 
            // Need x+y = pos+2 <= n-1 => pos <= n-3.
            if(pos <= n-3){
                doOp(pos+1, 1);
                pos = n-1;
            } else {
                // pos == n-2. Use op(1,1) to shuffle, then retry.
                doOp(1,1);
                for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                if(pos==placed) continue;
                if(pos < n-1 && pos <= n-3){
                    doOp(pos+1, 1);
                    pos = n-1;
                }
            }
        }

        if(pos != n-1){
            for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos==placed) continue;
        }

        // Step 2: move from n-1 to placed
        // op(x, y) with y including pos n-1. y = n-1-placed, x=1.
        // Element at n-1 in C, goes to (n-1)-(n-y) = (n-1)-(placed+1) = n-2-placed... 
        // Actually: i=n-1, in C since n-1 >= n-y = placed+1. Goes to i-(n-y) = n-1-placed-1 = n-2-placed? No.
        // Goes to i - (n-y) = (n-1) - (n - (n-1-placed)) = (n-1) - (placed+1) = n-2-placed. That's not placed.
        // Use x=1, y=n-1-placed. Element at n-1 goes to n-1-(placed+1)=n-2-placed. Hmm.
        // Try y=1: element at n-1 goes to 0. Then need to move from 0 to placed? 
        // Actually x = n-1-placed, y=1. Element in C goes to 0. Then placed elements shift right by 1... no they go to end.
        // Element at n-1: in C(y=1). Goes to index 0. But placed sorted elements are in A(x=n-1-placed), they go to end.
        // So sorted prefix gets broken. Bad.

        // Better: x = placed, y = n-1-placed. x+y = n-1 < n. Good (if placed>=1).
        if(placed >= 1 && pos == n-1){
            doOp(placed, n-1-placed);
            // element at n-1 in C. Goes to (n-1)-(n-(n-1-placed)) = (n-1)-(placed+1) = n-placed-2.
            // Hmm that's wrong. Let me recalc. n-y = n-(n-1-placed)=placed+1. i=n-1 >= placed+1. So in C. Goes to i-(n-y)=n-1-placed-1=n-placed-2. Not placed.
            // I need to reconsider.
        }
        // Let me just use: op with x=1, y = n-1-placed. 
        // Wait, I need to be more careful about what lands where.
        // Scrap step 2 above and redo.
        if(pos==n-1){
            int y0 = n - 1 - placed;
            int x0 = 1;
            // need x0+y0 <= n-1: 1+n-1-placed = n-placed. <=n-1 iff placed>=1.
            if(placed>=1){
                doOp(x0, y0);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
